<script>(function(){var mobile=<?= !empty($editor_mobile)?'true':'false'; ?>;function sync(){if(document.activeElement&&document.activeElement.matches('input,textarea'))return;var target=matchMedia('(max-width:768px), (max-width:1024px) and (orientation:portrait)').matches;if(target!==mobile){var url=new URL(location.href);if(target)url.searchParams.set('screen','mobile');else url.searchParams.delete('screen');location.replace(url);}}sync();window.addEventListener('resize',sync);})();</script>
